package main

import (
	"crypto/sha256"
	"encoding/hex"
	"os"
	"path/filepath"
	"regexp"
	"testing"

	"github.com/stricttools/strictspec/go/strictspec"
)

// Generated code pairs with the runtime on the generated-code format, never on
// the release string: a validator generated by one release keeps compiling
// against a later runtime for as long as the emitted shape is unchanged. The
// pin below records the emitted shape of one fixed input, so a change to what
// the Go emitter writes cannot ship without moving the format.
//
// When TestEmittedShapeIsPinned fails, the emitter writes something different
// than when the pin was taken. Generated code in the wild was written to the
// old shape: bump strictspec.MaxGeneratedCodeFormat (and the minimum, when the
// old shape is no longer read), then record the new format and hash here in the
// same commit.
const (
	pinnedGeneratedCodeFormat = 2
	pinnedEmittedShape        = "7056cfc542219d3a5db15b618f3553f8dd986206c48b075ae180e35c38afeca8"
)

var (
	releaseInSource = regexp.MustCompile(`GENERATED_BY = "[^"]*"`)
	releaseInHeader = regexp.MustCompile(`strictspec generator: .*`)
)

// emittedShape hashes one generated source with the generating release
// normalized away: a release bump does not move it, and any change to what the
// emitter writes does.
func emittedShape(src string) string {
	normalized := releaseInSource.ReplaceAllString(src, `GENERATED_BY = "<release>"`)
	normalized = releaseInHeader.ReplaceAllString(normalized, "strictspec generator: <release>")
	sum := sha256.Sum256([]byte(normalized))
	return hex.EncodeToString(sum[:])
}

func TestEmittedShapeIsPinned(t *testing.T) {
	if pinnedGeneratedCodeFormat != strictspec.MaxGeneratedCodeFormat {
		t.Fatalf("the pin records generated-code format %d, but the generator writes %d; the pin and the format move together",
			pinnedGeneratedCodeFormat, strictspec.MaxGeneratedCodeFormat)
	}
	// Only the schema and the type-definition file it imports: generated code
	// embeds every scalar manifest beside the schema, so copying unrelated
	// fixtures would move the hash on edits that do not touch the emitter.
	work := t.TempDir()
	for _, name := range []string{"shared-canvas.toml", "types-geometry.toml"} {
		copyFile(t, filepath.Join(fixturesSchemas(t), name), filepath.Join(work, name))
	}
	writeFile(t, filepath.Join(work, "strictspec.toml"), `format_version = 1
[[schemas]]
path = "shared-canvas.toml"
[[schemas.targets]]
lang = "go"
output = "gen/validator_gen.go"
package = "gen"
`)
	t.Chdir(work)
	if r := newApp().Test([]string{"gen", "--manifest", "strictspec.toml"}); r.ExitCode != 0 {
		t.Fatalf("gen exit = %d: %s", r.ExitCode, r.Stderr)
	}
	src, err := os.ReadFile(filepath.Join(work, "gen", "validator_gen.go"))
	if err != nil {
		t.Fatal(err)
	}
	if got := emittedShape(string(src)); got != pinnedEmittedShape {
		t.Fatalf("the emitted shape changed (pinned %s, got %s): bump strictspec.MaxGeneratedCodeFormat, then record the new format and hash in this file",
			pinnedEmittedShape, got)
	}
}
